package org.tomdang.critter.runtime;
import org.junit.jupiter.api.Test;import org.tomdang.critter.definition.*;import org.tomdang.gameplay.event.GameplayEventBus;import org.tomdang.gameplay.event.type.*;import org.tomdang.platform.threading.MainThreadGuard;import java.time.Duration;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class CritterRuntimeServiceTest{
	@Test void observesCapturesAndIsolatesOwners(){var registry=new CritterRegistry();registry.register(definition());registry.seal();var events=new GameplayEventBus(new MainThreadGuard(()->true));var observed=new ArrayList<CritterObserved>();var captured=new ArrayList<CritterCaptured>();events.subscribe(CritterObserved.class,observed::add);events.subscribe(CritterCaptured.class,captured::add);var service=new CritterRuntimeService(registry,events);UUID first=UUID.randomUUID(),second=UUID.randomUUID();var one=service.spawn("FLY",first);var two=service.spawn("FLY",second);service.approach(one.instanceId(),false);service.observe(one.instanceId());service.capture(one.instanceId());assertTrue(service.find(one.instanceId()).isEmpty());assertTrue(service.find(two.instanceId()).isPresent());assertEquals(List.of(new CritterObserved(first,"FLY")),observed);assertEquals(List.of(new CritterCaptured(first,"FLY")),captured);}
	private CritterDefinition definition(){return new CritterDefinition("FLY","Fly","LUMINA",CritterRarity.COMMON,Set.of("FOREST"),Set.of(Temperament.DOCILE),new CritterMovement(Set.of(MovementType.HOVERING),5,1,1,Duration.ofSeconds(1),3),new CritterHunting(Set.of(HuntingArchetype.OBSERVE),5,Duration.ofSeconds(3),2,CaptureOutcome.CAPTURED_AND_RELEASED),new CritterRewards(10,Map.of()),"PLACEHOLDER","",Set.of());}
}
